import { createContext, useContext } from "react";

export type Theme = "light" | "dark" | "system";
export type ResolvedTheme = "light" | "dark";

export const THEMES: readonly Theme[] = ["light", "dark", "system"];

/** The localStorage key ThemeProvider and the no-flash script in index.html share. */
export const THEME_STORAGE_KEY = "ui-theme";

export const DARK_QUERY = "(prefers-color-scheme: dark)";

export function isTheme(value: unknown): value is Theme {
  return typeof value === "string" && (THEMES as readonly string[]).includes(value);
}

/** The theme actually drawn: "system" follows the OS. */
export function resolveTheme(theme: Theme, prefersDark: boolean): ResolvedTheme {
  if (theme === "system") return prefersDark ? "dark" : "light";
  return theme;
}

/** Puts the resolved theme on <html> as shadcn expects: a `dark` class, or none. */
export function applyTheme(root: { classList: DOMTokenList }, theme: ResolvedTheme): void {
  root.classList.remove("light", "dark");
  root.classList.add(theme);
}

export type ThemeContextValue = {
  /** What the person chose. */
  theme: Theme;
  /** What is drawn, with "system" resolved. */
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: Theme) => void;
};

export const ThemeContext = createContext<ThemeContextValue>({
  theme: "system",
  resolvedTheme: "light",
  setTheme: () => {},
});

export function useTheme(): ThemeContextValue {
  return useContext(ThemeContext);
}

import { describe, expect, it } from "vitest";
import { applyTheme, isTheme, resolveTheme } from "./theme";

function fakeRoot(initial: string[] = []) {
  const set = new Set(initial);
  return {
    classList: {
      add: (...names: string[]) => names.forEach((n) => set.add(n)),
      remove: (...names: string[]) => names.forEach((n) => set.delete(n)),
    } as unknown as DOMTokenList,
    set,
  };
}

describe("resolveTheme", () => {
  it("keeps an explicit choice", () => {
    expect(resolveTheme("light", true)).toBe("light");
    expect(resolveTheme("dark", false)).toBe("dark");
  });

  it("follows the OS for system", () => {
    expect(resolveTheme("system", true)).toBe("dark");
    expect(resolveTheme("system", false)).toBe("light");
  });
});

describe("isTheme", () => {
  it("accepts the three names only", () => {
    expect(isTheme("light")).toBe(true);
    expect(isTheme("system")).toBe(true);
    expect(isTheme("sepia")).toBe(false);
    expect(isTheme(null)).toBe(false);
  });
});

describe("applyTheme", () => {
  it("swaps the class on the root", () => {
    const root = fakeRoot(["dark", "keep"]);
    applyTheme(root, "light");
    expect([...root.set].sort()).toEqual(["keep", "light"]);
  });
});

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { usePersisted } from "@/ui/use-persisted";
import {
  applyTheme,
  DARK_QUERY,
  isTheme,
  resolveTheme,
  THEME_STORAGE_KEY,
  ThemeContext,
  type Theme,
} from "@/ui/theme";

/**
 * shadcn's Vite theme provider: light, dark or system, remembered in localStorage and
 * applied as a class on <html>. Pair it with the script in index.html so the first
 * paint is already in the right theme.
 */
export function ThemeProvider({
  children,
  defaultTheme = "system",
  storageKey = THEME_STORAGE_KEY,
}: {
  children: ReactNode;
  defaultTheme?: Theme;
  storageKey?: string;
}) {
  const [theme, setTheme] = usePersisted<Theme>(storageKey, defaultTheme, isTheme);
  const [prefersDark, setPrefersDark] = useState(
    () => typeof window !== "undefined" && window.matchMedia(DARK_QUERY).matches,
  );

  useEffect(() => {
    const query = window.matchMedia(DARK_QUERY);
    const onChange = () => setPrefersDark(query.matches);
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, []);

  const resolvedTheme = resolveTheme(theme, prefersDark);

  useEffect(() => {
    applyTheme(document.documentElement, resolvedTheme);
  }, [resolvedTheme]);

  const value = useMemo(
    () => ({ theme, resolvedTheme, setTheme }),
    [theme, resolvedTheme, setTheme],
  );
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}
